<?php
declare(strict_types=1);
require_once __DIR__ . '/../includes/auth.php';
if (!admin_check()) { redirect('admin/login.php?return=quotations'); }
require_once __DIR__ . '/../includes/quotation_booking.php';
require_once __DIR__ . '/../includes/quotation_pdf.php';
try { $row = quote_get((int) get_input('id', 0)); } catch (InvalidArgumentException) { http_response_code(404); exit('Quotation not found.'); }
$adminTitle = 'Quotation booking'; $adminPage = 'quotations'; $d = $row['document'];
$binding = fetch_one('SELECT * FROM quotation_bookings WHERE quotation_id=:id', ['id' => $row['quotation_id']]);
$plan = $binding ? fetch_one('SELECT * FROM customer_itinerary_plans WHERE id=:id', ['id' => $binding['plan_id']]) : null;
$documents = ict_policy_published_documents(); $snapshot = count($documents) === 4 ? ict_policy_acceptance_snapshot($documents) : null;
$guestAcceptance = $plan && $plan['customer_user_id'] === null ? fetch_one('SELECT * FROM quotation_guest_acceptances WHERE plan_id=:id ORDER BY id DESC LIMIT 1', ['id' => $plan['id']]) : null;
$selected = (string) get_input('option', $binding['option_key'] ?? 'A'); if (!in_array($selected, ['A', 'B'], true)) { $selected = 'A'; }
$reference = $row['reference'] . ' R' . $row['revision'] . ' Option ' . $selected;
$ready = false; $bindingError = '';
if ($plan) { try { ict_confirmation_atomic(static function () use ($plan, &$ready): void { quote_assert_binding((int) $plan['id']); $ready = true; }); } catch (RuntimeException $error) { $bindingError = $error->getMessage(); } }
require __DIR__ . '/_top.php'; ?>
<link rel="stylesheet" href="<?= e(base_url('assets/css/quotations.css')) ?>">
<section class="quote-shell"><a href="<?= e(base_url('admin/quotation_edit.php?id=' . $row['id'])) ?>">← Quotation</a><div class="quote-heading"><div><p class="quote-eyebrow"><?= e($reference) ?></p><h1>Review the booking</h1><p>Choose the agreed services before creating or updating a plan.</p></div></div><div id="quote-message" role="alert"></div>
<form method="get" class="quote-panel"><input type="hidden" name="id" value="<?= (int) $row['id'] ?>"><label class="quote-field">Selected quotation option<select name="option"><?php foreach ($d['options'] as $key => $o): if (!$o['enabled']) { continue; } ?><option value="<?= $key ?>" <?= $selected === $key ? 'selected' : '' ?>><?= e($key . ': ' . $o['label']) ?></option><?php endforeach; ?></select></label><button class="btn btn-outline-dark mt-3">Review this option</button></form>
<section class="quote-panel"><h2><?= e($d['title']) ?></h2><p><?= e($d['customer']['name']) ?> · <?= e($d['customer']['phone']) ?></p><p>Arrival <?= e(str_replace('T', ' ', $d['arrival'])) ?> · Departure <?= e(str_replace('T', ' ', $d['departure'])) ?></p><?php if ($d['options'][$selected]['enabled'] && $row['state'] !== 'draft'): ?><div class="quote-total"><?= e($d['currency']) ?> <?= quote_money(quote_option_total($d, $selected)) ?> · group total</div><?php endif; ?>
<?php foreach ($d['days'] as $day): ?><h3 class="mt-3"><?= e(quote_day_label($day) . ': ' . $day['title']) ?></h3><p><?= nl2br(e($day['plan'])) ?></p><?php foreach ($day['activities'] as $a): ?><p><?= e($a['name']) ?> · <?= e(quote_status_label($a['status'][$selected])) ?></p><?php endforeach; ?><?php endforeach; ?>
<?php if ($selected === 'A'): foreach ($d['hotels'] as $h): ?><p><strong><?= e($h['name']) ?></strong> <?= e($h['alternative']) ?> · <?= (int) $h['nights'] ?> nights · <?= e($h['room']) ?> · <?= e($h['occupancy']) ?> · <?= e($h['meals']) ?></p><?php endforeach; endif; ?>
<?php if ($bindingError): ?><p class="alert alert-warning"><?= e($bindingError) ?></p><?php endif; ?>
<?php if ($plan): ?><p><strong>Linked plan #<?= (int) $plan['id'] ?> · <?= e(ict_booking_status_label($plan['booking_status'])) ?></strong><br><?= $plan['customer_user_id'] === null ? 'Guest · admin-managed booking' : 'Customer account #' . (int) $plan['customer_user_id'] ?></p><a href="<?= e(base_url('admin/inquiries.php#inquiry-' . $plan['contact_inquiry_id'])) ?>">Open linked inquiry</a><?php endif; ?>
<?php if ($row['state'] === 'issued' && (!$plan || $plan['booking_status'] !== 'confirmed')): ?><form id="conversion-form" class="mt-4"><label class="quote-field">Existing customer account ID (leave 0 for guest)<input type="number" name="customer_id" inputmode="numeric" min="0" value="<?= (int) ($plan['customer_user_id'] ?? 0) ?>" <?= $plan ? 'readonly' : '' ?>></label><p class="quote-help">Use a verified existing account ID to connect an account-based booking. Guest bookings require no account.</p><?php if ($plan): ?><label class="quote-check"><input type="checkbox" name="replace_reviewed">I reviewed replacing the existing unconfirmed plan with these services. Previous acceptance will require renewal.</label><?php endif; ?><button class="btn btn-success mt-2">Convert selected option to booking</button></form><?php endif; ?></section>
<?php if ($plan && $plan['customer_user_id'] === null && $plan['booking_status'] !== 'confirmed'): ?>
<section class="quote-panel"><h2>Admin-recorded customer acceptance</h2><p>Record the customer's actual agreement through WhatsApp or email. Keep supporting records privately; enter only a reference here.</p>
<?php if ($snapshot && $ready && (int) $binding['revision_id'] === (int) $row['id'] && $binding['option_key'] === $selected): ?>
<details class="mb-3"><summary>Exact current policies to share and verify</summary><?php foreach ($documents as $policy): ?><h3><?= e($policy['title']) ?></h3><p class="quote-help">Version <?= e($policy['version']) ?></p><?= $policy['content'] ?><?php endforeach; ?></details>
<form id="guest-accept-form"><div class="quote-grid"><label class="quote-field">Customer identity/name<input name="customer_name" maxlength="190" value="<?= e($d['customer']['name']) ?>" required></label><label class="quote-field">Acceptance channel<select name="channel"><option value="whatsapp">WhatsApp</option><option value="email">Email</option></select></label><label class="quote-field">Customer accepted at (Sri Lanka time)<input type="datetime-local" name="accepted_at" value="<?= e(str_replace(' ', 'T', substr(quote_now(), 0, 16))) ?>" required></label><label class="quote-field">Private evidence reference<input name="evidence_reference" maxlength="190" required></label></div><label class="quote-check mt-3"><input name="all_policies" type="checkbox" value="1" required>I verified agreement to this exact quotation option and all four displayed policies.</label><button class="btn btn-outline-success">Record customer acceptance</button></form>
<?php else: ?><p class="alert alert-warning">Acceptance requires the current converted revision/option and all four published policies. Review conversion or policy availability.</p><?php endif; ?></section>
<?php if ($guestAcceptance && $ready && ict_policy_plan_acceptance_state($plan, $documents)['ready_to_confirm']): ?>
<section class="quote-panel"><h2>Issue written confirmation</h2><p>Admin-recorded <?= e($guestAcceptance['channel']) ?> acceptance: <?= e($guestAcceptance['accepted_at']) ?> · <?= e($guestAcceptance['evidence_reference']) ?></p><?php $confirmationPlanId = (int) $plan['id']; $confirmationAcceptance = $guestAcceptance; require __DIR__ . '/_booking_confirmation_form.php'; ?></section>
<?php endif; endif; ?>
<?php if ($plan && $plan['customer_user_id'] !== null): ?><section class="quote-panel"><h2>Customer account acceptance</h2><p>Continue through the existing inquiry controls to request the customer's policy acceptance and complete the operator checks.</p><a class="btn btn-outline-success" href="<?= e(base_url('admin/inquiries.php#inquiry-' . $plan['contact_inquiry_id'])) ?>">Continue in inquiry</a></section><?php endif; ?>
</section>
<script type="application/json" id="quote-config"><?= json_encode(['csrf' => csrf_token(), 'api' => base_url('admin/quotation_api.php'), 'id' => (int) $row['id'], 'option' => $selected, 'plan' => (int) ($plan['id'] ?? 0), 'hash' => $snapshot['hash'] ?? ''], JSON_HEX_TAG | JSON_HEX_AMP | JSON_HEX_APOS | JSON_HEX_QUOT) ?></script>
<script src="<?= e(base_url('assets/js/quotation-common.js')) ?>" defer></script><script src="<?= e(base_url('assets/js/quotation-booking.js')) ?>" defer></script>
